begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('12000000-0000-0000-0000-000000000001'),('12000000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"12000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.journal_entries(id,title,body) values('22000000-0000-0000-0000-000000000001','Synthetic audio','Private synthetic writing')$$,'legacy entry insert remains compatible');
select lives_ok($$select public.reserve_voice_note('22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000001',640044,20)$$,'A reserves owned recording');
select throws_ok($$update public.journal_entries set voice_notes='[{"id":"32000000-0000-0000-0000-000000000001","title":"Test","start":10,"end":19,"share":false}]'$$,'23514',null,'unconfirmed upload cannot attach');
select throws_ok($$select public.voice_gateway_record('ready','{"id":"32000000-0000-0000-0000-000000000001"}')$$,'42501',null,'client cannot impersonate gateway');
reset role;
select public.voice_gateway_record('ready','{"id":"32000000-0000-0000-0000-000000000001"}');
set local role authenticated;
select lives_ok($$update public.journal_entries set voice_notes='[{"id":"32000000-0000-0000-0000-000000000001","title":"Test","start":10,"end":19,"share":false}]'$$,'confirmed private note saves');
select throws_ok($$update public.journal_entries set voice_notes='[{"id":"32000000-0000-0000-0000-000000000001","title":"Test","start":10,"end":21,"share":false}]'$$,'23514',null,'range cannot exceed real recording');
select throws_ok($$update public.journal_entries set voice_notes='[{"id":"32000000-0000-0000-0000-000000000001","title":"Test","start":10,"end":19,"share":false,"url":"https://evil.test"}]'$$,'23514',null,'unknown audio fields rejected');
select set_config('request.jwt.claims','{"sub":"12000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.journal_entries),0,'B cannot read A audio metadata');
select throws_ok($$select public.reserve_voice_note('22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000002',640044,20)$$,null,null,'B cannot upload to A entry');
select lives_ok($$insert into public.journal_entries(id,title,body)values('22000000-0000-0000-0000-000000000002','B','Private')$$,'B has separate entry');
select throws_ok($$update public.journal_entries set voice_notes='[{"id":"32000000-0000-0000-0000-000000000001","title":"Stolen","start":0,"end":1,"share":false}]'$$,'23514',null,'B cannot attach A recording');
select throws_ok($$select * from deardaily_private.voice_assets$$,'42501',null,'hidden audio ownership table inaccessible');
select set_config('request.jwt.claims','{"sub":"12000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.public_stories(id,user_id,title,body)values('22000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','Public','Approved writing')$$,'publication without audio remains compatible');
select throws_ok($$update public.public_stories set voice_notes='[{"id":"32000000-0000-0000-0000-000000000001","title":"Test","start":10,"end":19}]'$$,'23514',null,'private ID cannot become public');
reset role;
select public.voice_gateway_record('stage',jsonb_build_object('id','42000000-0000-0000-0000-000000000001','source_id','32000000-0000-0000-0000-000000000001','user_id','12000000-0000-0000-0000-000000000001','entry_id','22000000-0000-0000-0000-000000000001','version',(select version from public.journal_entries where id='22000000-0000-0000-0000-000000000001')));
set local role authenticated;
select throws_ok($$update public.public_stories set voice_notes='[{"id":"42000000-0000-0000-0000-000000000001","title":"Test","start":10,"end":19}]'$$,'23514',null,'unapproved source cannot publish');
update public.journal_entries set voice_notes=jsonb_set(voice_notes,'{0,share}','true') where id='22000000-0000-0000-0000-000000000001';
reset role;
update deardaily_private.voice_copies set version=(select version from public.journal_entries where id='22000000-0000-0000-0000-000000000001');
set local role authenticated;
select lives_ok($$update public.public_stories set voice_notes='[{"id":"42000000-0000-0000-0000-000000000001","title":"Test","start":10,"end":19}]'$$,'explicitly approved snapshot publishes');
select throws_ok($$update public.public_stories set voice_notes='[{"id":"42000000-0000-0000-0000-000000000001","title":"Test","start":0,"end":19}]'$$,'23514',null,'wider unapproved segment cannot publish');
update public.journal_entries set voice_notes='[]' where id='22000000-0000-0000-0000-000000000001';
reset role;
update deardaily_private.voice_assets set created_at=now()-interval '2 hours';
select public.voice_gateway_record('prune','{"user_id":"12000000-0000-0000-0000-000000000001"}');
select is((select count(*)::int from deardaily_private.voice_assets),1,'cleanup preserves sources needed by independent public snapshots');
set local role anon;
select is((select voice_notes->0->>'title' from public.public_stories),'Test','public snapshot independent of private editing');
select throws_ok($$select voice_notes from public.journal_entries$$,'42501',null,'anonymous cannot read private recordings');
select throws_ok($$select user_id from public.public_stories$$,'42501',null,'public interface hides ownership');
select throws_ok($$select public.reserve_voice_note('22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000002',44,1)$$,'42501',null,'anonymous upload denied');
select is((select count(*)::int from storage.objects where bucket_id in ('deardaily-voice-private','deardaily-voice-public')),0,'storage listing reveals no objects');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"12000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
delete from public.public_stories where id='22000000-0000-0000-0000-000000000001';
reset role;
select is((select count(*)::int from deardaily_private.voice_copies),0,'unpublish revokes staged public copies');
select is((select count(*)::int from deardaily_private.voice_assets),1,'unpublish preserves private audio');
select ok((select bool_and(not public) from storage.buckets where id in ('deardaily-voice-private','deardaily-voice-public')),'both buckets private');
select * from finish();rollback;
